// Capacitor definition
//
// CAP_KIND selects the physical unit:
//   "MOSCAP" (default) -- the gate-oxide MOS capacitor the taped-out chip
//                         used (SARADC_CELL_INVX16_ASCAP).  Non-linear:
//                         C(V) swings ~1.8x over the switching range.
//   "MOM"              -- the lateral metal fringe cap generated by
//                         gen/analog/layout_mom_cap.py (SARADC_CAP_MOM).
//                         Voltage-independent, DRC/LVS/PEX proven per PDK.
//
// The module ports are unchanged on purpose: the analog hierarchy passes
// VNW/VPW (AVDD/VSS) and VSH/FL; the MOM cell's substrate terminal is the
// existing VPW, so no caller has to change.

(* keep_hierarchy = "yes" *)
module SARADC_CAP #(
  parameter CAP_KIND = "MOSCAP"
) (
  inout VNW, VPW,
  inout VSH, FL // TODO: Ask Li why those names
);

  generate
    if (CAP_KIND == "MOM") begin : mom
      SARADC_CAP_MOM impl (
        .VSH(VSH), .FL(FL), .VSS(VPW)
      );
    end else begin : moscap
      SARADC_CELL_INVX16_ASCAP impl (
    //`ifdef WITH_BODY
        .vnw(VNW), .vpw(VPW),
    //`endif
        .vdd(FL), .vss(FL),
        .i(VSH), .zn(FL)
      );
    end
  endgenerate

endmodule
